// Keep material graph operations shared; only geometry inputs differ per frame.
// This transformation consumes generated source, never user-authored shader text.
const variables=[['uv','vec2'],['uvX','vec2'],['uvY','vec2'],['normal','vec3'],['normalX','vec3'],['normalY','vec3'],['pointX','vec3'],['pointY','vec3']],args='pointer,id,point,view,result,width,timeContext';
export function shareRayProgramInputs(source){
 const functions=new Map(),pattern=/\bvec4 (hbRay(?:Previous)?Program\d+)\(([^)]*)\)\{/g;let match;
 while((match=pattern.exec(source))){let at=pattern.lastIndex,depth=1;for(;at<source.length&&depth;at++){if(source[at]==='{')depth++;else if(source[at]==='}')depth--;}if(depth)throw Error('생성 머테리얼 함수의 끝을 확인하세요.');const body=source.slice(pattern.lastIndex,at-1),graphAt=body.indexOf('{vec4 value=hbGeometryLoad(');if(graphAt<0)continue;const prefix=body.slice(0,graphAt),registers=prefix.match(/vec4 r[XY]?\d+=vec4\(0,0,0,0\);/g)||[];functions.set(match[1],{name:match[1],signature:match[2],start:match.index,end:at,geometry:prefix.replace(/vec4 r[XY]?\d+=vec4\(0,0,0,0\);/g,''),registers:registers.join(''),graph:body.slice(graphAt)});pattern.lastIndex=at;}
 const edits=[];let programs=0;for(const row of functions.values()){if(!/^hbRayProgram\d+$/.test(row.name))continue;const previous=functions.get(row.name.replace('hbRayProgram','hbRayPreviousProgram'));if(row.signature!=='float pointer,float id,vec3 point,vec3 view,vec4 result,float width,vec2 timeContext')continue;if(!previous||row.graph!==previous.graph||row.registers!==previous.registers||row.signature!==previous.signature)continue;const inputs=variables.filter(([name])=>new RegExp('\\b'+name+'\\b').test(row.graph));if(!inputs.length&&!row.geometry&&!previous.geometry){edits.push({start:previous.start,end:previous.end,value:'vec4 '+previous.name+'('+previous.signature+'){return '+row.name+'('+args+');}'});}else{const name=row.name.replace('hbRayProgram','hbRayProgramValues'),parameters=inputs.map(([name,type])=>','+type+' '+name).join(''),values=inputs.map(([name])=>','+name).join(''),helper='vec4 '+name+'('+row.signature+parameters+'){'+row.registers+row.graph+'}\n';for(const [entry,first]of[[row,true],[previous,false]])edits.push({start:entry.start,end:entry.end,value:(first?helper:'')+'vec4 '+entry.name+'('+entry.signature+'){'+entry.geometry+'return '+name+'('+args+values+');}'});}programs++;}
 let result=source;for(const edit of edits.sort((a,b)=>b.start-a.start))result=result.slice(0,edit.start)+edit.value+result.slice(edit.end);return{source:result,programs,bytesBefore:source.length,bytesAfter:result.length};
}
